  const earlyMorning = new Date("2026-11-23T08:00:00Z");
  const lateEvening = new Date("2026-11-23T18:00:00Z");
  assert.equal(canShip(earlyMorning), false);
  assert.equal(canShip(lateEvening), false);
});

