  const mondayMorning = new Date("2026-11-23T09:00:00Z");
  const mondayAfternoon = new Date("2026-11-23T15:00:00Z");
  const fridayAfternoon = new Date("2026-11-27T17:59:00Z");
  assert.equal(canShip(mondayMorning), true);
  assert.equal(canShip(mondayAfternoon), true);
  assert.equal(canShip(fridayAfternoon), true);
});

